import math

class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        moduli = [2, 3, 4, 7, 9]

        # For last digit d (nonzero), if g = gcd(10, d), then
        # (10*x + d) % d == 0  iff  x % (d/g) == 0.
        m_for_digit = [0] * 10
        for d in range(1, 10):
            m_for_digit[d] = d // math.gcd(10, d)

        counts = {m: [0] * m for m in moduli}
        prev_total = 0  # number of substrings ending at p-1 before processing p
        ans = 0

        for p, ch in enumerate(s):
            a = ord(ch) - 48

            if a != 0:
                d = a
                m = m_for_digit[d]
                if m == 1:
                    prev_div = prev_total
                else:
                    prev_div = counts[m][0]
                ans += 1 + prev_div

            new_counts = {m: [0] * m for m in moduli}
            for m in moduli:
                old = counts[m]
                new = new_counts[m]
                for x in range(m):
                    c = old[x]
                    if c:
                        y = (10 * x + a) % m
                        new[y] += c
                new[a % m] += 1  # substring consisting of this digit only
            counts = new_counts
            prev_total += 1

        return ans

