from functools import lru_cache
from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        L = sum(nums)
        if abs(k) > L:
            return -1

        # max_sum[i]: maximum absolute alternating sum contribution from suffix i
        # max_prod[i]: maximum possible product of a subsequence from suffix i (skip zeros), capped at limit
        max_sum = [0] * (n + 1)
        max_prod = [1] * (n + 1)
        for i in range(n - 1, -1, -1):
            max_sum[i] = max_sum[i + 1] + nums[i]
            p = max_prod[i + 1]
            if nums[i] > 1:
                p *= nums[i]
                if p > limit:
                    p = limit
            max_prod[i] = p

        size = 2 * L + 1
        # reach[i][parity][d + L] == 1 iff some subsequence from nums[i:] (any product)
        # can produce alternating contribution d when the next chosen element has given parity.
        reach = [None] * (n + 1)
        reach[n] = [bytearray(size), bytearray(size)]
        reach[n][0][L] = 1
        reach[n][1][L] = 1

        for i in range(n - 1, -1, -1):
            x = nums[i]
            cur = [None, None]
            for p in (0, 1):
                q = 1 - p
                sign = 1 if p == 0 else -1
                c = sign * x
                base = bytearray(reach[i + 1][p])  # skip nums[i]
                added = bytearray(size)
                source = reach[i + 1][q]
                # taking nums[i]: d = d2 + c, where d2 is achievable from i+1 with parity q
                for di in range(size):
                    if source[di]:
                        td = di + c
                        if 0 <= td < size:
                            added[td] = 1
                arr = bytearray(size)
                for idx in range(size):
                    if base[idx] or added[idx]:
                        arr[idx] = 1
                cur[p] = arr
            reach[i] = cur

        @lru_cache(maxsize=None)
        def best(i: int, p: int, d: int, cap: int) -> int:
            """
            Maximum product q of a subsequence from nums[i:] (possibly empty) such that
            its alternating contribution d is achieved and q <= cap.
            Returns -1 if impossible. Empty sequence has product 1.
            """
            if abs(d) > max_sum[i]:
                return -1
            if cap >= max_prod[i]:
                cap = max_prod[i]
            if i == n:
                return 1 if d == 0 else -1
            if not reach[i][p][d + L]:
                return -1

            val = best(i + 1, p, d, cap)  # skip nums[i]
            x = nums[i]
            sign = 1 if p == 0 else -1
            d2 = d - sign * x
            np_ = 1 - p

            if abs(d2) <= max_sum[i + 1]:
                if x == 0:
                    # Product becomes 0; remaining elements may be chosen arbitrarily as long as d2 is achievable.
                    if reach[i + 1][np_][d2 + L]:
                        if 0 > val:
                            val = 0
                else:
                    new_cap = cap // x
                    qres = best(i + 1, np_, d2, new_cap)
                    if qres != -1:
                        cand = x * qres
                        if cand > val:
                            val = cand
            return val

        ans = -1
        # The first chosen element is at even position. Enumerate it.
        for j in range(n):
            x = nums[j]
            if x == 0:
                val = 0 if reach[j + 1][1][k + L] else -1
            else:
                new_cap = limit // x
                qres = best(j + 1, 1, k - x, new_cap)
                val = x * qres if qres != -1 else -1
            if val > ans:
                ans = val
        return ans

class Solution:
    def countSubstrings(self, s: str) -> int:
        moduli = (2, 3, 4, 7, 9)
        counts = {m: [0] * m for m in moduli}
        # For current last digit d, condition 10*x ≡ 0 mod d reduces to x ≡ 0 mod (d/gcd(10,d))
        m_for_digit = [0, 1, 1, 3, 2, 1, 3, 7, 4, 9]

        total_prev = 0  # number of substrings ending at previous position
        ans = 0

        for ch in s:
            a = ord(ch) - 48

            if a != 0:
                m = m_for_digit[a]
                good_prev = total_prev if m == 1 else counts[m][0]
                ans += 1 + good_prev

            new_counts = {m: [0] * m for m in moduli}
            for m in moduli:
                old = counts[m]
                new = new_counts[m]
                ten_mod = 10 % m
                for x in range(m):
                    c = old[x]
                    if c:
                        y = (ten_mod * x + a) % m
                        new[y] += c
                new[a % m] += 1  # substring consisting only of current digit
            counts = new_counts
            total_prev += 1

        return ans

